79	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
80	    @Override
81	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
82	        Collection<Owner> owners;
83	        if (lastName != null) {
84	            owners = this.clinicService.findOwnerByLastName(lastName);
85	        } else {
86	            owners = this.clinicService.findAllOwners();
87	        }
88	        if (owners.isEmpty()) {
89	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
90	        }
91	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
92	    }
93	
94	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
95	    @Override
96	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
97	        Owner owner = this.clinicService.findOwnerById(ownerId);
98	        if (owner == null) {
99	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
100	        }
101	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
102	    }
103	
104	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
105	    @Override
106	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
107	        HttpHeaders headers = new HttpHeaders();
108	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
109	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
110	        owner.setTelephone(normalizedTelephone);
111	        owner.setEmail(normalizeEmail(owner.getEmail()));
112	        owner.setAddress(normalizeAddress(owner.getAddress()));
113	        if (owner.getRegistrationDate() == null) {
114	            owner.setRegistrationDate(LocalDate.now());
115	        }
116	        if (isTelephoneInUse(normalizedTelephone, null)) {
117	            throw new ResponseStatusException(HttpStatus.CONFLICT,
118	                "telephone is already in use by another owner");
119	        }
120	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
121	        if (!sharesHousehold
122	            && this.clinicService.isHouseholdInUse(owner.getLastName(), owner.getAddress(), null)) {
123	            throw new ResponseStatusException(HttpStatus.CONFLICT,
124	                "another owner with the same last name already lives at this address");
125	        }
126	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
127	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
128	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
129	        if (sharesHousehold) {
130	            this.clinicService.assignHousehold(owner);
131	        }
132	        this.clinicService.saveOwner(owner);
133	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
134	        headers.setLocation(UriComponentsBuilder.newInstance()
135	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
136	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
137	    }
138	
139	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
140	    @Override
141	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
142	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
143	        if (currentOwner == null) {
144	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
145	        }
146	        currentOwner.setAddress(ownerFieldsDto.getAddress());
147	        currentOwner.setCity(ownerFieldsDto.getCity());
148	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
149	        currentOwner.setLastName(ownerFieldsDto.getLastName());
150	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
151	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
152	        this.clinicService.saveOwner(currentOwner);
153	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
154	    }
155	
156	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
157	    @Transactional
158	    @Override
159	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
160	        Owner owner = this.clinicService.findOwnerById(ownerId);
161	        if (owner == null) {
162	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
163	        }
164	        this.clinicService.deleteOwner(owner);
165	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
166	    }
167	
168	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
169	    @Override
170	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
171	        Owner owner = this.clinicService.findOwnerById(ownerId);
172	        if (owner == null) {
173	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
174	        }
175	        HttpHeaders headers = new HttpHeaders();
176	        Pet pet = petMapper.toPet(petFieldsDto);
177	        owner.setId(ownerId);
178	        pet.setOwner(owner);
179	        pet.getType().setName(null);
180	        this.clinicService.savePet(pet);
181	        PetDto petDto = petMapper.toPetDto(pet);
182	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
183	            .buildAndExpand(pet.getId()).toUri());
184	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
185	    }
186	
187	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
188	    @Override
189	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
190	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
191	        if (currentOwner != null) {
192	            Pet currentPet = this.clinicService.findPetById(petId);
193	            if (currentPet != null) {
194	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
195	                currentPet.setName(petFieldsDto.getName());
196	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
197	                this.clinicService.savePet(currentPet);
198	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
199	            }
200	        }
201	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
202	    }
