204	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
205	    @Override
206	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
207	        HttpHeaders headers = new HttpHeaders();
208	        Visit visit = visitMapper.toVisit(visitFieldsDto);
209	        Pet pet = new Pet();
210	        pet.setId(petId);
211	        visit.setPet(pet);
212	        this.clinicService.saveVisit(visit);
213	        VisitDto visitDto = visitMapper.toVisitDto(visit);
214	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
215	            .buildAndExpand(visit.getId()).toUri());
216	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
217	    }
